import { useState, type ChangeEvent, type FormEvent } from 'react';
import { Button, Card, Input, Stack, Text, Toast } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const [toastOpen, setToastOpen] = useState(false);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!email.trim()) return;
    setEmail('');
    setToastOpen(true);
  };

  return (
    <Card style={{ padding: 'var(--jx-space-6)', maxWidth: 'var(--jx-size-sm)' }}>
      <form onSubmit={handleSubmit} noValidate={false}>
        <Stack direction="column" gap="var(--jx-space-4)">
          <Text as="h2" variant="heading-sm">
            Подписка на рассылку
          </Text>
          <Input
            type="email"
            name="email"
            label="Почта"
            placeholder="you@example.com"
            autoComplete="email"
            required
            value={email}
            onChange={(event: ChangeEvent<HTMLInputElement>) => setEmail(event.target.value)}
          />
          <Button type="submit" variant="primary">
            Подписаться
          </Button>
        </Stack>
      </form>

      <Toast
        open={toastOpen}
        onOpenChange={setToastOpen}
        placement="bottom-right"
        status="success"
        duration={4000}
        title="Готово"
        description="Письмо отправлено на указанный адрес."
      />
    </Card>
  );
}

